import { describe, expect, it } from 'vitest';
import { setup } from './helpers';

const createTenant = (send: ReturnType<typeof setup>['send'], body: unknown) =>
  send('/admin/tenants', { method: 'POST', body: JSON.stringify(body) });

describe('admin API', () => {
  it('lists the seeded tenants', async () => {
    const { send } = setup();
    const body = (await (await send('/admin/tenants')).json()) as { tenants: Array<{ id: string }> };
    expect(body.tenants.map((t) => t.id)).toEqual(['tenant-a', 'tenant-b']);
  });

  it('creates a tenant', async () => {
    const { send } = setup();
    const res = await createTenant(send, { id: 'tenant-c', name: 'Tenant C' });
    expect(res.status).toBe(201);
    expect(await res.json()).toMatchObject({ id: 'tenant-c', name: 'Tenant C' });
  });

  it('refuses a duplicate tenant id', async () => {
    const { send } = setup();
    expect((await createTenant(send, { id: 'tenant-a', name: 'Again' })).status).toBe(409);
  });

  it('refuses an invalid tenant id', async () => {
    const { send } = setup();
    expect((await createTenant(send, { id: 'Not Valid', name: 'x' })).status).toBe(400);
    expect((await createTenant(send, { name: 'no id' })).status).toBe(400);
  });

  it('lets a new tenant receive webhooks', async () => {
    const { send, postWebhook } = setup();
    await createTenant(send, { id: 'tenant-c', name: 'Tenant C' });
    expect((await postWebhook('tenant-c', { type: 'hello' })).status).toBe(202);
  });
});
